import{_ as t,o,c as a,ag as d}from"./chunks/framework.DHSXpJLs.js";const f=JSON.parse('{"title":"项目介绍","description":"","frontmatter":{},"headers":[],"relativePath":"guide/intro.md","filePath":"guide/intro.md","lastUpdated":1790780265000}'),r={name:"guide/intro.md"};function c(i,e,s,n,l,h){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="项目介绍" tabindex="-1">项目介绍 <a class="header-anchor" href="#项目介绍" aria-label="Permalink to &quot;项目介绍&quot;">​</a></h1><p>SourceAEC 是一个自托管、开源的建筑 3D 建模平台，目标是让 AI 和设计师高效协作。它围绕一个核心构想构建：</p><blockquote><p>AI 读 skill，写 Python 构建脚本；脚本经 IfcOpenShell 或 ezdxf 执行，产出 IFC 模型或 DXF 图纸。Python 脚本是模型的唯一事实源，前端的一切修改组件最终改的都是脚本。</p></blockquote><p>这样做的好处很直接。模型文件可以随时从脚本重建，存储很轻；版本控制就是脚本的版本控制；两个模型的差异就是两份脚本的差异，可以精确算出来。完整概念与操作见<a href="/SourceAEC/guide/editing">编辑与版本</a>。</p><h2 id="两条对等管线-外加一个推荐项" tabindex="-1">两条对等管线，外加一个推荐项 <a class="header-anchor" href="#两条对等管线-外加一个推荐项" aria-label="Permalink to &quot;两条对等管线，外加一个推荐项&quot;">​</a></h2><p><strong>逻辑一：AI 生成 IFC，已交付。</strong> <code>skills/aiifc</code> 是给 AI 的建模参考包，<code>services/ifc</code> 是服务端运行时，负责脚本沙箱执行、版本快照、语义对比和编辑 API。</p><p><strong>逻辑二：AI 生成 CAD，已交付。</strong> <code>skills/aiplan</code> 把外部资料整理成任务书，<code>skills/aidxf</code> 把任务书画成逐层 DXF 图纸；<code>services/cad</code> 与 ifc 侧同构。</p><p><strong>推荐项：Agent 工作流，已落地。</strong> 平台内置 Eino chat agent，按项目类型派发 ifc 或 cad 子 agent。网页右侧的 AI 对话栏就是它驱动的，不需要外部 agent 服务。</p><p>可复用性是设计原则：两个 skill、两个业务服务都可以单独拿出来用，前端和 PostgreSQL 都是可选的。</p><h2 id="面向谁" tabindex="-1">面向谁 <a class="header-anchor" href="#面向谁" aria-label="Permalink to &quot;面向谁&quot;">​</a></h2><ul><li>要<strong>自托管 BIM 工具链</strong>的团队：数据不出自己的机器，不依赖任何云服务。</li><li>做 <strong>IFC 或 CAD 工具</strong>的开发者：<code>services/ifc</code> 与 <code>services/cad</code> 可脱离前端单独部署和移植。</li><li>需要**「AI 可接入的编辑底座」**的研究者：人和 AI 共用同一套编辑 API，来源用 provenance 字段区分。</li></ul><p>当前端到端可用：创建项目 → AI 生成模型 → 三维或二维审查 → 提 Issue → 定位脚本并修改 → 沙箱验证 → 保存大版本 → 对比版本差异。走一遍见<a href="/SourceAEC/guide/first-project">创建第一个项目</a>。</p><h2 id="组件一览" tabindex="-1">组件一览 <a class="header-anchor" href="#组件一览" aria-label="Permalink to &quot;组件一览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>技术</th><th>职责</th></tr></thead><tbody><tr><td><code>web</code></td><td>React 19，xeokit 与 web-ifc 双引擎，DXF 用 Fabric Canvas</td><td>项目库、查看器、编辑面板、Issue、Diff、AI 对话栏</td></tr><tr><td><code>server</code></td><td>Go 1.26</td><td>唯一对外入口（:8090）：REST API、转换队列、编辑编排、chat agent，并托管前端构建产物</td></tr><tr><td><code>converter</code></td><td>Node CLI</td><td>把 IFC 转成 XKT 几何和元数据，由 server 当子进程调用</td></tr><tr><td><code>services/ifc</code></td><td>Python FastAPI + IfcOpenShell</td><td>IFC 脚本沙箱、版本、定位、语义对比（:8100）</td></tr><tr><td><code>services/cad</code></td><td>Python FastAPI + ezdxf</td><td>DXF 脚本沙箱、版本、对比、render.json 发布（:8200）</td></tr><tr><td><code>services/sandbox</code></td><td>共享包 <code>aibim_sandbox</code></td><td>bwrap 沙箱后端与 script-as-source 领域模块，被两个服务引用</td></tr><tr><td><code>skills/</code></td><td>SKILL.md 加参考文档</td><td>aiifc、aiplan、aidxf 等 skill，AI 侧入口，可脱离平台单独分发</td></tr></tbody></table><p>三个语言并存是生态现实：Go 适合网关，Python 绑定 IfcOpenShell 和 ezdxf，Node 绑定 xeokit 转换器。服务之间用 REST 和子进程解耦，任何组件都可以单独替换。详见<a href="/SourceAEC/development/architecture">总体架构</a>。</p><h2 id="部署形态" tabindex="-1">部署形态 <a class="header-anchor" href="#部署形态" aria-label="Permalink to &quot;部署形态&quot;">​</a></h2><p>宿主机直接运行，不用 Docker。生产环境只有 8090 一个端口：Go server 托管前端构建产物，浏览器只访问它。不配 PostgreSQL 也能跑，数据默认落文件；<strong>鉴权默认关闭，生产环境必须设置 token</strong>。步骤见<a href="/SourceAEC/guide/deploy">生产部署与运维</a>。</p><h2 id="许可" tabindex="-1">许可 <a class="header-anchor" href="#许可" aria-label="Permalink to &quot;许可&quot;">​</a></h2><p>SourceAEC 以 Apache-2.0 发布，见 <a href="https://github.com/0702hjj/SourceAEC/blob/main/LICENSE" target="_blank" rel="noreferrer">LICENSE</a>。例外目录保留原许可：<code>skills/aiplan</code>、<code>skills/aidxf</code> 为 MIT。完整清单见根目录 <a href="https://github.com/0702hjj/SourceAEC/blob/main/NOTICE" target="_blank" rel="noreferrer">NOTICE</a>。</p><p>需要特别注意 xeokit：<code>web/</code> 前端依赖 AGPL-3.0 的 <code>@xeokit/xeokit-sdk</code>，分发包含它的前端构建产物时，整个产物受 AGPL 约束，网络使用即触发。闭源或商用场景请改走 three.js 加 web-ifc 的路径。converter 以子进程方式使用 xeokit-convert，它输出的 XKT 数据不受 AGPL 覆盖。</p>',20)])])}const u=t(r,[["render",c]]);export{f as __pageData,u as default};
